143	// The L3-REAL decoder megakernel needs the token path + a grad-partial workspace
144	// in addition to the FuseTier::{L1,L3} ABI. We keep it a SEPARATE kernel +
145	// launcher (not folded into fused_megakernel) so the surrogate path is untouched.
146	//
147	// Workspace layout (one flat float buffer the host allocates + the kernel owns):
148	//   [0 .. nCTA*total)              : per-CTA grad partials (cta-major)
149	//   [nCTA*total .. nCTA*total+nCTA): per-CTA loss partials (NLL sum per slice)
150	//   [.. +1)                        : the reduced scalar loss (loss/B) the host reads
151	// total == kDecTotalElems == 422755.
152	
153	struct DecoderTokenCtx {
154	    const int* tokens;   // [B, kSeq] int32 token ids in [0, kVocab)
155	    const int* targets;  // [B]       int32 target ids
156	    int        B;        // batch size (full-batch in the race ≈ 4191)
157	    float*     workspace; // grad partials + loss partials + reduced loss
158	    float*     loss_out;  // device float the kernel writes the mean loss into
159	};
