161	// ── The persistent megakernel (L3-REAL). gridDim.x = #SMs (one CTA/SM), 256
162	//    threads/CTA. The smem holds ONE DecSampleSmem (≈42 KB, < 48 KB static cap —
163	//    no dynamic-smem opt-in, so the occupancy≥1 guard with dynamicSMemBytes=0 in
164	//    the launcher is unchanged). ────────────────────────────────────────────────
165	// sizes/offsets are NOT host-passed: the per-tensor numel/offset live in the
166	// generated __constant__ tables kDecSizes/kDecOffsets (decoder_layout.cuh), so
167	// the reduce + optimizer phases read them directly. This also lets the host side
168	// (dispatch.cpp) avoid building any layout tensors.
169	template <OptId Opt>
170	__global__ void __launch_bounds__(SG_TUNED_MEGA_BLOCK)
171	fused_decoder_megakernel(PersistentContext ctx,
172	                         float* __restrict__ params,
173	                         DecoderTokenCtx tok,
174	                         float* __restrict__ grad,        // reduced grad [total]
175	                         float lr, int step, FusedOptState st) {
176	    __shared__ DecSampleSmem sm;
177	    GridBarrier bar = ctx.barrier();
178	    const int cta = blockIdx.x;
179	    const int nCTA = (int)ctx.n_ctas;
180	    const int64_t total = kDecTotalElems;
181	    float* my_partial = tok.workspace + (int64_t)cta * total;   // this CTA's dW
182	    float* loss_part = tok.workspace + (int64_t)nCTA * total;   // [nCTA]
183	
184	    // §3.4 register repartition (producer WG gives back, consumer WG claims).
185	    const int wg = threadIdx.x / 128;
186	    // warp-specialize prims live in sg::sm90::wgs (this file is sg::fused::sm90)
187	    if (wg == 0) ::sg::sm90::wgs::warpgroup_reg_dealloc<32>();
188	    else         ::sg::sm90::wgs::warpgroup_reg_alloc<200>();
189	
190	    // ── P0: zero this CTA's grad-partial slice + its loss slot. ───────────────
191	    for (int64_t i = threadIdx.x; i < total; i += blockDim.x) my_partial[i] = 0.0f;
192	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
193	    bar.sync();   // B0
194	
195	    // ── P1: batch-parallel fwd+bwd. Fixed contiguous slice [b0,b1) for this CTA.
196	    DecWeights w = dec_bind(params);
197	    DecGrad g = dec_bind_grad(my_partial);
198	    // Even split with remainder to the low CTAs (contiguous, deterministic).
199	    const int B = tok.B;
200	    const int base = B / nCTA, rem = B % nCTA;
201	    const int b0 = cta * base + (cta < rem ? cta : rem);
202	    const int cnt = base + (cta < rem ? 1 : 0);
203	    const int b1 = b0 + cnt;
204	    __shared__ int tok_s[dec::kSeq];   // this sample's token ids (broadcast)
205	    __shared__ int tgt_s;
206	    float nll_acc = 0.0f;              // fp32 slice accumulator (thread-0 holds it)
207	    for (int b = b0; b < b1; ++b) {
208	        if (threadIdx.x < dec::kSeq) tok_s[threadIdx.x] = tok.tokens[(int64_t)b * dec::kSeq + threadIdx.x];
209	        if (threadIdx.x == 0) tgt_s = tok.targets[b];
210	        __syncthreads();
211	        float nll = dec_forward_sample(w, tok_s, tgt_s, &sm);
212	        dec_backward_sample(w, g, tok_s, tgt_s, B, &sm);
213	        if (threadIdx.x == 0) nll_acc += nll;   // fixed-order fp32 sum within slice
214	        __syncthreads();   // sample boundary: all grad writes done before reuse
215	    }
216	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
217	    bar.sync();   // B1: all CTA partials + loss slots complete
218	
219	    // ── P2: deterministic cross-CTA reduce. Work-steal the param ELEMENT-RANGES
220	    //    (one task = one parameter tensor; sum its elements across CTAs in
221	    //    ascending CTA index). The summation ORDER (ascending cta) is fixed, so
222	    //    the result is deterministic regardless of which CTA grabs the task. ────
223	    {
224	        __shared__ int task_slot;
225	        TaskQueue q = ctx.queue();
226	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
227	             t = q.next_block(&task_slot)) {
228	            const int n = kDecSizes[t];
229	            const int64_t off = (int64_t)kDecOffsets[t];
230	            for (int i = threadIdx.x; i < n; i += blockDim.x) {
231	                float acc = 0.0f;
232	                // ascending CTA index → fixed fp32 summation order (deterministic).
233	                for (int c = 0; c < nCTA; ++c)
234	                    acc += tok.workspace[(int64_t)c * total + off + i];
235	                grad[off + i] = acc;
236	            }
237	        }
238	    }
239	    // Loss reduction (fp64 ordered) by CTA 0 only — the 1e-5 loss rel-tol is the
240	    // tightest gate; fp32 atomic-summing ~4191 terms can miss it.
241	    if (cta == 0 && threadIdx.x == 0) {
242	        double s = 0.0;
243	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
244	        float mean = (float)(s / (double)B);
245	        *tok.loss_out = mean;
246	    }
247	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue for P3
248	
249	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 30
250	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
251	    st.lr = lr;
252	    {
253	        __shared__ int task_slot;
254	        TaskQueue q = ctx.queue();
255	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
256	             t = q.next_block(&task_slot)) {
257	            const int n = kDecSizes[t];
258	            const int64_t off = (int64_t)kDecOffsets[t];
259	            const FusedOptState ts = rebase_state<Opt>(st, off);
260	            float* __restrict__ p = params + off;
261	            const float* __restrict__ gg = grad + off;
262	            for (int i = threadIdx.x; i < n; i += blockDim.x)
263	                apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
264	        }
265	    }
266	}
